USE school_football_db;



-- Update statuses for active and upcoming rounds
UPDATE ROUNDS 
SET status = 'Active' 
WHERE round_id IN (SELECT r_id FROM (SELECT round_id AS r_id FROM ROUNDS ORDER BY round_id DESC LIMIT 2) AS t);

UPDATE ROUNDS 
SET status = 'Upcoming' 
WHERE round_id IN (SELECT r_id FROM (SELECT round_id AS r_id FROM ROUNDS ORDER BY round_id DESC LIMIT 2 OFFSET 2) AS t);